import pytest
from candidate import decode_shift, encode_shift


class TestDecodeShift:
    def test_decode_single_letter_a_encoded(self):
        assert decode_shift('f') == 'a'

    def test_decode_single_letter_b_encoded(self):
        assert decode_shift('g') == 'b'

    def test_decode_single_letter_z_encoded(self):
        assert decode_shift('e') == 'z'

    def test_decode_single_letter_a_raw(self):
        assert decode_shift('a') == 'v'

    def test_decode_single_letter_b_raw(self):
        assert decode_shift('b') == 'w'

    def test_decode_single_letter_e_raw(self):
        assert decode_shift('e') == 'z'

    def test_decode_multiple_letters(self):
        assert decode_shift('mjqqt') == 'hello'

    def test_decode_word_hello(self):
        assert decode_shift(encode_shift('hello')) == 'hello'

    def test_decode_word_world(self):
        assert decode_shift(encode_shift('world')) == 'world'

    def test_decode_all_lowercase_roundtrip(self):
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        assert decode_shift(encode_shift(alphabet)) == alphabet

    def test_decode_empty_string(self):
        assert decode_shift('') == ''

    def test_decode_repeated_same_char(self):
        assert decode_shift('fffff') == 'aaaaa'

    def test_decode_all_z_encoded(self):
        assert decode_shift('eeeee') == 'zzzzz'

    def test_decode_wraparound_boundary(self):
        assert decode_shift('abcde') == 'vwxyz'

    def test_decode_long_string_roundtrip(self):
        s = 'a' * 1000
        assert decode_shift(encode_shift(s)) == s

    def test_decode_mixed_case_string(self):
        s = 'aAbBcCdDeE'
        encoded = encode_shift(s)
        assert decode_shift(encoded) == s

    def test_decode_uppercase_letter(self):
        assert decode_shift('F') == 'u'

    def test_decode_uppercase_A(self):
        assert decode_shift('A') == 'p'

    def test_decode_digit_zero(self):
        assert decode_shift('0') == 'y'

    def test_decode_space_character(self):
        assert decode_shift(' ') == 'i'

    def test_decode_exclamation_mark(self):
        assert decode_shift('!') == 'j'

    def test_decode_with_none_raises_type_error(self):
        with pytest.raises(TypeError):
            decode_shift(None)

    def test_decode_with_integer_raises_type_error(self):
        with pytest.raises(TypeError):
            decode_shift(42)

    def test_decode_with_boolean_raises_type_error(self):
        with pytest.raises(TypeError):
            decode_shift(True)

    def test_decode_with_tuple_raises_type_error(self):
        with pytest.raises(TypeError):
            decode_shift((1, 2, 3))

    def test_decode_with_none_in_list(self):
        with pytest.raises(TypeError):
            decode_shift([None])

    def test_decode_double_roundtrip(self):
        s = 'testing'
        once = encode_shift(s)
        twice = encode_shift(once)
        decoded_once = decode_shift(twice)
        assert decoded_once == once
        assert decode_shift(decoded_once) == s

    def test_decode_full_cycle_all_letters(self):
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        result = alphabet
        for _ in range(26):
            result = decode_shift(encode_shift(result))
        assert result == alphabet

    def test_decode_shift_by_exactly_5(self):
        assert decode_shift(encode_shift('q')) == 'q'
        assert decode_shift(encode_shift('m')) == 'm'
        assert decode_shift(encode_shift('x')) == 'x'

    def test_decode_shift_preserves_length(self):
        s = 'abcde'
        assert len(decode_shift(encode_shift(s))) == len(s)

    def test_decode_only_returns_lowercase_alpha_for_lowercase_input(self):
        for ch in 'abcdefghijklmnopqrstuvwxyz':
            result = decode_shift(ch)
            assert 'a' <= result <= 'z'

    def test_decode_none_input_raises(self):
        with pytest.raises((TypeError, AttributeError)):
            decode_shift(None)

    def test_decode_float_input_raises(self):
        with pytest.raises(TypeError):
            decode_shift(3.14)
